function Get-VcoFirstNonEmptyEnvValue {
    param([string[]]$Names)

    foreach ($name in @($Names)) {
        if (-not $name) { continue }
        $value = [Environment]::GetEnvironmentVariable([string]$name)
        if (-not [string]::IsNullOrWhiteSpace([string]$value)) {
            return [string]$value
        }
    }

    return $null
}

